code.solution:
package main

import (
	"fmt"
	"sort"
	"sync"
)

func main() {
	var (
		mu  sync.Mutex
		wg  sync.WaitGroup
		out []string
	)
	for _, v := range []string{"a", "b", "c"} {
		wg.Add(1)
		go func(v string) { // v is now a per-goroutine parameter copy
			defer wg.Done()
			mu.Lock()
			out = append(out, v) // collect to print deterministically
			mu.Unlock()
		}(v) // pass the current v explicitly
	}
	wg.Wait()
	sort.Strings(out) // goroutine order isn't deterministic; sort for stable output
	for _, v := range out {
		fmt.Println(v)
	}
}

