package solution

import "testing"

func TestMemoizeCaches(t *testing.T) {
	calls := 0
	slow := func(n int) int {
		calls++ // count how many times the underlying fn runs
		return n * n
	}
	m := Memoize(slow)
	if got := m(4); got != 16 {
		t.Fatalf("m(4)=%d want 16", got)
	}
	if got := m(4); got != 16 { // cached
		t.Fatalf("m(4) cached=%d want 16", got)
	}
	if calls != 1 {
		t.Fatalf("underlying fn called %d times, want 1", calls)
	}
	if got := m(5); got != 25 || calls != 2 {
		t.Fatalf("m(5)=%d calls=%d want 25,2", got, calls)
	}
}

